INSERT INTO `weibo_note` VALUES (1, '2656274875', '央视新闻', 'https://tvax4.sinaimg.cn/crop.0.0.690.690.180/002TLsr9ly8iakuy3heb6j60j60j6wex02.jpg?KID=imgbed,tva&Expires=1780997161&ssig=b071MhTMtI', 'm', 'https://m.weibo.cn/u/2656274875?luicode=20000061&lfid=5307822046970372&launchid=10000360-page_H5', '', 1780986384824, 1780986384824, 5307822046970372, '#原来高考还没结束#【#多地高考3天或4天#一起为考生加油，胜利在望！】#多地25日可高考查分# 昨天，2026年全国高考统考科目考试全部结束。高考综合改革省份因科目设置不同，今天和明天还安排有思想政治、地理、化学、生物等选考科目考试。截至目前，海南、山东、山西、重庆、广东、湖北、江西等地已公布高考查分时间，多地6月25日可查。你哪一年高考？当时考了几天？转发分享，祝福考生！ 央视新闻的微博视频', 1780995653, '2026-06-09 09:00:53+08:00', '1657', '433', '242', 'https://m.weibo.cn/detail/5307822046970372', '高考');
INSERT INTO `weibo_note` VALUES (2, '2370219502', '吉姆快开车', 'https://tvax1.sinaimg.cn/crop.0.0.640.640.180/8d46adeely8ff9hfgirhjj20hs0hs75g.jpg?KID=imgbed,tva&Expires=1780997159&ssig=uAG5r0sB7O', 'm', 'https://m.weibo.cn/u/2370219502?launchid=10000360-page_H5', '上海', 1780986384838, 1780986384838, 5307611349516877, '2026高考数学全国1卷，网友表示这难度答案照抄，都要看看时间够不够#高考##高考数学难度# 上海 ', 1780945419, '2026-06-08 19:03:39+08:00', '16762', '756', '3043', 'https://m.weibo.cn/detail/5307611349516877', '高考');
INSERT INTO `weibo_note` VALUES (3, '7817489471', '笑死了但没完全死', 'https://tvax4.sinaimg.cn/crop.0.0.1080.1080.180/008x3o7Rly8idfh9rz0adj30u00u0my7.jpg?KID=imgbed,tva&Expires=1780997159&ssig=lfht3Zdbbb', 'f', 'https://m.weibo.cn/u/7817489471?launchid=10000360-page_H5', '北京', 1780986384852, 1780986384852, 5307210825730031, '8296高考作文写这个直接满分 ', 1780849927, '2026-06-07 16:32:07+08:00', '3560', '211', '357', 'https://m.weibo.cn/detail/5307210825730031', '高考');
INSERT INTO `weibo_note` VALUES (4, '2992050891', '北京时间', 'https://tvax4.sinaimg.cn/crop.0.0.821.821.180/003gul7lly8h8vg84tqdwj60mt0mtmy302.jpg?KID=imgbed,tva&Expires=1780997165&ssig=QRMf7uoqRe', 'm', 'https://m.weibo.cn/u/2992050891?luicode=20000061&lfid=5307494492013476&launchid=10000360-page_H5', '', 1780986384864, 1780986384864, 5307494492013476, '【#梁实以为有2小时其实只有75分钟#】6月8日，59岁“高考钉子户”梁实参加第30次高考，在走出考场后懊悔表示：今天考历史出了点问题，考试的时候以为考2小时，结果才发现考试时长只有75分钟。一开始还在慢慢写，力求把这个字写得很工整，结果到后面题还没写完，说只有半个小时了，最后完成的很匆忙。#高考历史##高考物理##历史二卷 盲人摸象#（记者：王易楚） 北京时间的微博视频', 1780917558, '2026-06-08 11:19:18+08:00', '2289', '115', '57', 'https://m.weibo.cn/detail/5307494492013476', '高考');
INSERT INTO `weibo_note` VALUES (5, '3536826167', '快乐储存所', 'https://tvax1.sinaimg.cn/crop.0.0.512.512.180/d2cfaf37ly8gr3wlqhsvlj20e80e8mxe.jpg?KID=imgbed,tva&Expires=1780997159&ssig=cnKMSI%2FCGA', 'm', 'https://m.weibo.cn/u/3536826167?launchid=10000360-page_H5', '湖南', 1780986384879, 1780986384879, 5307562970843517, '高考学校门口挂零了，今天还要去吗 ', 1780933885, '2026-06-08 15:51:25+08:00', '36935', '520', '42', 'https://m.weibo.cn/detail/5307562970843517', '高考');
INSERT INTO `weibo_note` VALUES (6, '6718735909', '你直男就别卖了呗', 'https://tvax3.sinaimg.cn/crop.0.0.1080.1080.180/007kH88dly8iaijnpikcoj30u00u0dgo.jpg?KID=imgbed,tva&Expires=1780997169&ssig=xZoZVE7qA9', 'f', 'https://m.weibo.cn/u/6718735909?luicode=20000061&lfid=5307883493524852&launchid=10000360-page_H5', '山东', 1780986384890, 1780986384890, 5307883493524852, '#高考政治#ok好了终于在热搜上见到你了 你知道吗我高中三年从来没做过这么难的卷子 好吧确实有可能是我们学校的原因 但是选择题我不知道您是什么意思 还有后面大题能说是创新吗 本来是评析题的经济与社会 现在是国际经济与政治。还有后面的论文题本来应该是必修一现在直接成文化了是什么意思呢亲爱的。', 1781010303, '2026-06-09 13:05:03+08:00', '898', '69', '16', 'https://m.weibo.cn/detail/5307883493524852', '高考');
INSERT INTO `weibo_note` VALUES (7, '7817489471', '笑死了但没完全死', 'https://tvax4.sinaimg.cn/crop.0.0.1080.1080.180/008x3o7Rly8idfh9rz0adj30u00u0my7.jpg?KID=imgbed,tva&Expires=1780997159&ssig=lfht3Zdbbb', 'f', 'https://m.weibo.cn/u/7817489471?launchid=10000360-page_H5', '安徽', 1780986384902, 1780986384902, 5307612439774379, '8333【高考前复习】历史老师你干嘛我真的要不行了 ', 1780945679, '2026-06-08 19:07:59+08:00', '497', '12', '25', 'https://m.weibo.cn/detail/5307612439774379', '高考');
INSERT INTO `weibo_note` VALUES (8, '5386924056', '王玮晨', 'https://tvax4.sinaimg.cn/crop.0.0.480.480.180/005SyZ1Sly8i3tl9bvkkkj30dc0dc3yz.jpg?KID=imgbed,tva&Expires=1780997173&ssig=4Lx%2B5aCS84', 'm', 'https://m.weibo.cn/u/5386924056?luicode=20000061&lfid=5307845428908312&launchid=10000360-page_H5', '湖南', 1780986384916, 1780986384916, 5307845428908312, '高考重要性现在其实就已经弱化很多了。一个是学历大幅贬值，每年毕业 1200多万学生，市场根本没有那么多的白领岗位匹配。除开985 211，文凭在用人单位眼里没区别。考得好考得差，都到不了以前“一考定终身”的程度。另外是通路多，中产以上的家庭，很多方式可以绕过高考。真正现在能通过高考改变命运改变阶级的，可能就剩下农村或者城市底层，有读书天赋的孩子。其余的，考成啥样影响大差不差。之后到社会上决定发展的主要还是读书之外的能力，以及家庭资源。', 1781001228, '2026-06-09 10:33:48+08:00', '287', '97', '3', 'https://m.weibo.cn/detail/5307845428908312', '高考');
INSERT INTO `weibo_note` VALUES (9, '3911558393', '冷知识bot', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/e925a4f9ly8hx7uusrixhj20u00u0766.jpg?KID=imgbed,tva&Expires=1780997159&ssig=zNiDYc0slJ', 'f', 'https://m.weibo.cn/u/3911558393?launchid=10000360-page_H5', '重庆', 1780986384927, 1780986384927, 5307206845335523, '今天是高考作文“奖惩之后”十周年 ', 1780848978, '2026-06-07 16:16:18+08:00', '8009', '260', '568', 'https://m.weibo.cn/detail/5307206845335523', '高考');
INSERT INTO `weibo_note` VALUES (10, '3762961402', '崔庆龙_', 'https://tvax2.sinaimg.cn/crop.0.0.921.921.180/e04a3bfaly8hfi8a0j7w6j20pl0pl3zx.jpg?KID=imgbed,tva&Expires=1780997159&ssig=hpvJ7Bxa%2F5', 'm', 'https://m.weibo.cn/u/3762961402?launchid=10000360-page_H5', '四川', 1780986384939, 1780986384939, 5307882226059057, '高考，在过去总是被人视作是划定人生命运的一道分水岭，它确实算得上是一个强力系统变量，为了把握那个可能算得上是强力拐点的命运十字，一个家庭几乎会穷尽所有资源去倾注。也就是在有关高考话题层出不穷的这几天，我刚好受人推荐，看了前高考数学命题人葛军的一期播客。这一期播客提到了学习、考试 ...全文', 1781010001, '2026-06-09 13:00:01+08:00', '220', '13', '61', 'https://m.weibo.cn/detail/5307882226059057', '高考');
INSERT INTO `weibo_note` VALUES (11, '1676679984', '张雪峰老师', 'https://tvax2.sinaimg.cn/crop.0.0.1080.1080.180/001Ptb3yly8ibicnjqj0wj60u00u0wgj02.jpg?KID=imgbed,tva&Expires=1780997159&ssig=RYNoC0h4RV', 'm', 'https://m.weibo.cn/u/1676679984?launchid=10000360-page_H5', '江苏', 1780986384950, 1780986384950, 5307220986433200, '2026年高考到了，老张每年都会如约给大家送上祝福，今年张雪峰团队替老张来送祝福，我们永不缺席！ 张雪峰老师的微博视频 ', 1780852349, '2026-06-07 17:12:29+08:00', '82200', '2872', '2026', 'https://m.weibo.cn/detail/5307220986433200', '高考');
INSERT INTO `weibo_note` VALUES (12, '3933121907', '易金融厚道独立', 'https://tvax1.sinaimg.cn/crop.0.0.996.996.180/ea6ead73ly8fym9akuy5xj20ro0roabi.jpg?KID=imgbed,tva&Expires=1780997182&ssig=wQjJYEH9lX', 'm', 'https://m.weibo.cn/u/3933121907?luicode=20000061&lfid=5307903800246950&launchid=10000360-page_H5', '四川', 1780986384963, 1780986384963, 5307903800246950, '高考数理化各科目都难受本硕博数理化各科目都难受有一个题外话高考后一部分学员开始有了争取……博士毕业证……的机会了吧那么问题不大来了一个博士毕业证到底算不算＋是不是……天才苗子……证明书……呀？答案吗是……真不是譬＋如唐朝289年进士……总量＋总人数………7000左右二宋北宋＋南宋……一共320年进士总共……3万左右这是啥子意思呢？哪怕是凤毛麟角的进士中……也不是……也不可能是全部都是真正的天才苗子哦！更多是……书读百遍其义自见换言之天才文豪……只能是下面的＋那样的……苏轼李白杜甫李清照大姐＋鲁迅先生等等吧现代口水语文教育培养出来的文青应该是热热闹闹的传播学高产……是提现了传播学的附加值……并不是……神来……因为跃然纸上的文字功夫绝大多数都是文盲科盲的热热闹闹谈不上文学史灯塔级别档次文青的特长实际是……擅长……不服气擅长文凭＋擅长文痞那一套关键是还还恬不知耻＋还妄自尊大＋夸夸其谈', 1781015145, '2026-06-09 14:25:45+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903800246950', '高考');
INSERT INTO `weibo_note` VALUES (13, '7744708244', '花爷的日常', 'https://tvax2.sinaimg.cn/crop.0.0.512.512.180/008s80p6ly8hf8ezcx8kcj30e80e8q3d.jpg?KID=imgbed,tva&Expires=1780997159&ssig=6SdIUOOWmu', 'f', 'https://m.weibo.cn/u/7744708244?launchid=10000360-page_H5', '山东', 1780986509831, 1780986509831, 5307903785304356, '#对话高考那年的我#认真点说：高考完就不要再去想了，一切都是最好的宿缘和安排，旗开得胜。 ', 1781015140, '2026-06-09 14:25:40+08:00', '3', '1', '0', 'https://m.weibo.cn/detail/5307903785304356', '高考');
INSERT INTO `weibo_note` VALUES (14, '1678429834', '广东交通之声', 'https://tvax3.sinaimg.cn/crop.0.0.1000.1000.180/640ace8aly8hwno9uw1g8j20rs0rs3z8.jpg?KID=imgbed,tva&Expires=1780997159&ssig=5Jwg7eRuH2', 'm', 'https://m.weibo.cn/u/1678429834?launchid=10000360-page_H5', '', 1780986509854, 1780986509854, 5307903763810080, '2026年高考最后一日，考生穿西班牙球衣为自己打气，想用与球星一样“青春风暴”气势助威高考，作为球迷希望西班牙能在世界杯夺冠！#高考#1052高考收官日 #2026年高考 广东交通之声的微博视频 ', 1781015136, '2026-06-09 14:25:36+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903763810080', '高考');
INSERT INTO `weibo_note` VALUES (15, '7360641072', '河北---666', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/00828uZily8ic2qzy6jjdj30u00u0jtv.jpg?KID=imgbed,tva&Expires=1780997295&ssig=Sb%2FUolfDJO', 'm', 'https://m.weibo.cn/u/7360641072?luicode=20000061&lfid=5307903741526681&launchid=10000360-page_H5', '河北', 1780986509869, 1780986509869, 5307903741526681, '看着热搜上那些穿着校服、满脸胶原蛋白的孩子，恍惚间觉得像是看到了三十几年前的自己。那时候觉得高考是天大的事，少一分能哭半宿。现在在国企搬砖几年，再回头看，那其实只是人生无数个关卡里，最公平也最单纯的一个。没有KPI，没有复杂的人际关系，只要努力就有回响。今天很多省份选考科目也结束了，不管考得如何，先好好睡一觉，吃顿好的。接下来的志愿填报才是另一场“考试”，家长们别太焦虑，孩子们也别太迷茫。人生是旷野，不是轨道，高考很重要，但它决定不了你一生的幸福。祝各位考生，金榜题名，未来可期。🎓#高考##微博AI创作季#', 1781015131, '2026-06-09 14:25:31+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903741526681', '高考');
INSERT INTO `weibo_note` VALUES (16, '7924218410', '绿蚁新醅酒矣', 'https://tvax2.sinaimg.cn/crop.0.0.690.690.180/008Ehdcmly8hqb6f2gdovj30j60j6q45.jpg?KID=imgbed,tva&Expires=1780997299&ssig=BKO4tNBX2z', 'f', 'https://m.weibo.cn/u/7924218410?luicode=20000061&lfid=5307903724489580&launchid=10000360-page_H5', '山西', 1780986509881, 1780986509881, 5307903724489580, '开心消消乐#高考这局消消乐带你通关##开心消消乐# 高考季到了。大家都还记得自己坐在考场上是怎样的心境?是镇定自若还是迷茫期待。上一次参加高考已经十年前了，现在想想印象最深刻的就是高考前一天上午打扫卫生，有的同学拿着卷子从楼上扔下去，后来发展成为所有人都在扔，有学校领导在下面喊也止不住大家的疯狂，然后就叫来了门卫大叔和宿管阿姨让他们来打扫装袋，卖掉了，双赢了！下午，班主任老师给我们买了个蛋糕和小零食，大家坐在学校花池旁边聊天玩闹吃吃喝喝，偶尔还有调皮的同学把奶油抹到同学脸上，真是很欢乐的气氛了。从考试只剩一百天倒计时开始，每天都是紧张状态，这难得的轻松帮忙调节了一下心情，也让青春多了一点特殊的回忆。少年心性真的是不可再得，祝愿大家圆梦高考，心想事成', 1781015127, '2026-06-09 14:25:27+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903724489580', '高考');
INSERT INTO `weibo_note` VALUES (17, '1412484181', '德州新闻网官方微博', 'https://tvax4.sinaimg.cn/crop.0.0.190.190.180/5430cc55ly8h8vg7ca1gwj205a05a746.jpg?KID=imgbed,tva&Expires=1780997304&ssig=RVQpNjWvq5', 'm', 'https://m.weibo.cn/u/1412484181?luicode=20000061&lfid=5307903693030239&launchid=10000360-page_H5', '', 1780986509888, 1780986509888, 5307903693030239, '【#高考后接到这5类电话千万别信##付费AI报志愿避免滑档系骗局#】高考前后涉考诈骗进入高发期，诈骗分子常冒充教育局、高校招生办工作人员，利用考生和家长的焦虑设下陷阱。公安部刑侦局梳理出五大典型骗局：“你作弊了”，谎称考生考试作弊，借机索要罚款、套取信息；“花钱改分”，宣称可花钱找人后台改分；“内部指标，低分高录”，捏造高校内部补录指标，收取指标费；“提前查分”，发送虚假链接，盗取信息；“AI志愿填报”，售卖AI志愿填报服务，谎称可避免滑档。民警提醒，高考没有捷径可走，成绩、录取数据均无法人为篡改。各类所谓 “特殊渠道” 都是骗局，切勿轻信转账。请大家积极转发提醒亲友，远离高考诈骗，平安顺利上岸。#高考英语# 荔枝新闻的微博视频', 1781015119, '2026-06-09 14:25:19+08:00', '1', '1', '0', 'https://m.weibo.cn/detail/5307903693030239', '高考');
INSERT INTO `weibo_note` VALUES (18, '2485425080', '笑料百宝箱', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/942493b8ly8i007iqiyp7j20u00u1myr.jpg?KID=imgbed,tva&Expires=1780997159&ssig=hLFQiz4OXr', 'm', 'https://m.weibo.cn/u/2485425080?launchid=10000360-page_H5', '陕西', 1780986509898, 1780986509898, 5307869622961764, '全国多地高考今天结束，家长：此刻觉得车已到站，我已“下岗”！有一种心情叫做“高考结束”！超暖心! 孩子与家长的真情流露~ #高考加油# 笑料百宝箱的微博视频 ', 1781006996, '2026-06-09 12:09:56+08:00', '53', '2', '0', 'https://m.weibo.cn/detail/5307869622961764', '高考');
INSERT INTO `weibo_note` VALUES (19, '5201308915', '北京卫视生命缘', 'https://tvax3.sinaimg.cn/crop.0.0.1080.1080.180/005G0a3hly8h8vi4yrii9j30u00u0dgm.jpg?KID=imgbed,tva&Expires=1780997159&ssig=MX0eBQdTZq', 'f', 'https://m.weibo.cn/u/5201308915?launchid=10000360-page_H5', '', 1780986509907, 1780986509907, 5307903645849440, '高考考场上紧张，该如何缓解情绪？#高考##情绪##brtv生命缘# 北京卫视生命缘的微博视频 ', 1781015108, '2026-06-09 14:25:08+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903645849440', '高考');
INSERT INTO `weibo_note` VALUES (20, '6142716952', '对话陕西', 'https://tvax3.sinaimg.cn/crop.0.0.512.512.180/006HIdhSly8i2qqoj8hxqj30e80e8q3b.jpg?KID=imgbed,tva&Expires=1780997308&ssig=3Jp10s5FPE', 'm', 'https://m.weibo.cn/u/6142716952?luicode=20000061&lfid=5307903633523983&launchid=10000360-page_H5', '', 1780986509914, 1780986509914, 5307903633523983, '#高考第一波收官惊喜已抵达考场外#【#男生手作巨型花束为高考好友送祝福#】 6月9日，云南昆明昆一中考点外暖意浓浓。一名男生精心制作巨型花束等候考完的好友，表达祝福。考试结束，走出考场的女生不仅收到了来自好友的惊喜，也迎来了父母送上的鲜花。面对簇拥的花束，女生直呼花太大、人太多，都快抱不住了，连忙拿出手机定格这份美好。高考征程告一段落，愿学子们奔赴崭新人生！ @都市时报 都市时报的微博视频', 1781015105, '2026-06-09 14:25:05+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903633523983', '高考');
