INSERT INTO `weibo_note` VALUES (28, '2028810631', '新浪新闻', 'https://tvax4.sinaimg.cn/crop.0.0.799.799.180/002diGk7ly8h8vg36oqidj60m70m7mxs02.jpg?KID=imgbed,tva&Expires=1780997506&ssig=9PGKfYMytm', 'm', 'https://m.weibo.cn/u/2028810631?launchid=10000360-page_H5', '', 1780986718206, 1780986718206, 5307875515958965, '【#布伦森一级恶意犯规#】#马刺4分险胜尼克斯#NBA总决赛第三场，马刺战胜尼克斯。本场比赛的多次判罚引发争议，尤其是第三节比赛中，尚帕尼倒地三分投进打成3+1，落地时踩到布伦森脚轻微扭伤，裁判吹罚布伦森一级恶意犯规。#马刺1比2尼克斯#隆多的战术板的微博视频 ', 1781008401, '2026-06-09 12:33:21+08:00', '215', '66', '24', 'https://m.weibo.cn/detail/5307875515958965', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (29, '2769897145', '雷霆中文网', 'https://tvax2.sinaimg.cn/crop.0.0.400.400.180/a51946b9ly8i0mq7r4g09j20b40b43yk.jpg?KID=imgbed,tva&Expires=1780997506&ssig=Yuv8Ax42qw', 'f', 'https://m.weibo.cn/u/2769897145?launchid=10000360-page_H5', '', 1780986718214, 1780986718214, 5307868035154909, 'NBA总决赛第一次也是NBA历史上第一次出现这种情况。裁判把球给尼克斯队，都已经开球进攻了。马上吹停比赛让马刺队换人，硬保太明显了。 雷霆中文网的微博视频 ', 1781006618, '2026-06-09 12:03:38+08:00', '303', '129', '3', 'https://m.weibo.cn/detail/5307868035154909', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (30, '2302617634', '篮球大历史', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/893f2822ly8gdilf6ch77j20u00u075c.jpg?KID=imgbed,tva&Expires=1780997506&ssig=23EKIYduFP', 'm', 'https://m.weibo.cn/u/2302617634?launchid=10000360-page_H5', '福建', 1780986718223, 1780986718223, 5307865498913861, '尼克斯今天对阵马刺总决赛G3的全场集锦！错过比赛的可以来补补！非常精彩的一场比赛，马刺从领先到落后，然后重新拿回优势，第四节收尾超级精彩，卡斯尔、布伦森、福克斯都有关键球！太好看了！#马刺vs尼克斯##NBA总决赛##特朗普观战NBA总决赛# 篮球大历史的微博视频 ', 1781006013, '2026-06-09 11:53:33+08:00', '158', '4', '24', 'https://m.weibo.cn/detail/5307865498913861', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (31, '5602344347', '霍嫂说', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/00678RGHly8idbtagric3j30u00u0jva.jpg?KID=imgbed,tva&Expires=1780997506&ssig=T7sc%2B2jlqk', 'm', 'https://m.weibo.cn/u/5602344347?launchid=10000360-page_H5', '福建', 1780986718233, 1780986718233, 5307851427545153, '裁判第四节已经在帮了，联盟给的机会，是赛季结束，还是保有悬念，就看最后一哆嗦了。#马刺vs尼克斯##nba总决赛# ', 1781002657, '2026-06-09 10:57:37+08:00', '254', '57', '0', 'https://m.weibo.cn/detail/5307851427545153', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (32, '2318910945', '新浪热点', 'https://tvax3.sinaimg.cn/crop.0.0.450.450.180/002wVUFrly8h8vgt7mcs2j60ci0ci0t002.jpg?KID=imgbed,tva&Expires=1780997508&ssig=sk4mSX%2F1k6', 'm', 'https://m.weibo.cn/u/2318910945?luicode=20000061&lfid=5307891777015235&launchid=10000360-page_H5', '', 1780986718243, 1780986718243, 5307891777015235, '【#美国警察将尼克斯球迷头部砸向柱子#】#尼克斯球迷遭美警暴力执法# 美国《纽约邮报》8日曝光了11日NBA总决赛第二场（G2）赛后，纽约警察的暴力执法画面。一名警察抓住一名尼克斯队球迷的衣领，将他的头部砸向一旁柱子。现场其他球迷对警察发出嘘声，目前纽约警方并未对此作出回应。（海客新闻） #马刺1比2尼克斯# 新浪热点的微博视频', 1781012278, '2026-06-09 13:37:58+08:00', '68', '35', '33', 'https://m.weibo.cn/detail/5307891777015235', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (33, '5533010788', 'Love马刺', 'https://tvax4.sinaimg.cn/crop.55.0.671.671.180/0062rWRuly8grziarpfvlj30lp0inta5.jpg?KID=imgbed,tva&Expires=1780997512&ssig=EpScSARkpc', 'm', 'https://m.weibo.cn/u/5533010788?luicode=20000061&lfid=5307877694898949&launchid=10000360-page_H5', '浙江', 1780986718262, 1780986718262, 5307877694898949, '😰疯狂！美媒：尼克斯球迷袭击马刺球迷，撕烂了文班亚马球衣今日NBA总决赛G3马刺（1）115-111（2）战胜尼克斯。本场比赛，马刺球员维克托-文班亚马出战38分钟，投篮18中11，三分球4中2，罚球9中8，得到32分8篮板6助攻2抢断3盖帽。美媒分享视频：太疯狂了，尼克斯球迷赛后撕烂文班球迷身穿的文班球衣#NBA总决赛##马刺vs尼克斯##马刺1比2尼克斯# Love马刺的微博视频', 1781008921, '2026-06-09 12:42:01+08:00', '49', '18', '2', 'https://m.weibo.cn/detail/5307877694898949', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (34, '6354989284', '荔枝竞技', 'https://tvax2.sinaimg.cn/crop.0.0.1000.1000.180/006W4T1aly8i89q11sps6j30rs0rsq49.jpg?KID=imgbed,tva&Expires=1780997516&ssig=M1povg%2BY0C', 'f', 'https://m.weibo.cn/u/6354989284?luicode=20000061&lfid=5307905223164473&launchid=10000360-page_H5', '', 1780986718269, 1780986718269, 5307905223164473, '【#众星现身NBA总决赛G3赛场##NBA尼克斯主场门票有多贵#】北京时间6月9日，NBA季后赛G3精彩不断，麦迪逊花园群星云集，本场比赛场均票价约7768美元。大O与尤因领衔篮坛传奇亮相看台，甜茶、斯派克·李、本·斯蒂勒悉数到场，体坛与影视大咖同框吸睛。中场Cardi B登台献唱，动感舞台瞬间点燃现场氛围，全场球迷热情高涨。荔枝新闻的微博视频', 1781015484, '2026-06-09 14:31:24+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307905223164473', 'NBA总决赛');
