INSERT INTO `weibo_note` VALUES (37, '2193518494', '詹姆斯吧官方微博', 'https://tvax2.sinaimg.cn/crop.0.0.512.512.180/82be6f9ely8gjrnfl21pnj20e80e8mxm.jpg?KID=imgbed,tva&Expires=1780997506&ssig=pTuBT9D2Yv', 'm', 'https://m.weibo.cn/u/2193518494?launchid=10000360-page_H5', '上海', 1780986841285, 1780986841285, 5307854397637735, '看起来尼克斯今天难了 ', 1781003366, '2026-06-09 11:09:26+08:00', '87', '25', '1', 'https://m.weibo.cn/detail/5307854397637735', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (38, '6032330782', '小李聊球分析', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/006Af2NMly8ich0d9ailcj30u00u0gnz.jpg?KID=imgbed,tva&Expires=1780997622&ssig=FGZ3wi9UQ6', 'm', 'https://m.weibo.cn/u/6032330782?luicode=20000061&lfid=5307904803999092&launchid=10000360-page_H5', '江西', 1780986841293, 1780986841293, 5307904803999092, '🔥21岁创历史！文班亚马成魔术师后总决赛最年轻30+先生，马刺1-2绝境扳回一城！ 北京时间6月9日，2025-26赛季NBA总决赛G3打响，客场作战的马刺以115-111险胜尼克斯，将系列赛大比分扳为1-2。此役，文班亚马狂砍32分8篮板6助攻3盖帽，不仅带队终结尼克斯主场13连胜，更创下纪录，成为自魔术师约翰逊以来，NBA总决赛历史上最年轻的单场30分先生！ 这场胜利对马刺而言至关重要，此前两战全败的他们在麦迪逊花园打出团队篮球，6人得分上双，卡斯尔关键罚球锁定胜局。而文班亚马的全能表现，更是用攻防两端的统治力证明，他早已不是那个青涩的状元，而是能在总决赛舞台上扛起球队的未来超巨。 #文班创造总决赛纪录 #马刺vs尼克斯', 1781015384, '2026-06-09 14:29:44+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307904803999092', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (39, '1689485412', '绿茵小只', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/64b38064ly8ibzez5yq0mj20u00u0q3v.jpg?KID=imgbed,tva&Expires=1780997626&ssig=nWSwR4UgxB', 'm', 'https://m.weibo.cn/u/1689485412?luicode=20000061&lfid=5307904173540879&launchid=10000360-page_H5', '江西', 1780986841300, 1780986841300, 5307904173540879, '#马刺1比2尼克斯##nba总决赛# 总比分1-2！文班32+8+6 卡斯尔23分 马刺115-111尼克斯扳回一城 北京时间6月9日，2026年NBA总决赛第三场在尼克斯主场麦迪逊广场花园打响。客场作战的圣安东尼奥马刺以115-111险胜纽约尼克斯，将系列赛大比分改写为1-2，拒绝被对手拿到赛点 。 比赛回顾：剧情跌宕起伏，末节决胜 - 首节（33-22）：马刺反客为主，打出7-0完美开局，文班亚马内线强攻+外线发威，卡斯尔续上火力，马刺单节净胜11分，建立两位数领先。- 次节（24-42）：尼克斯强势反扑，布伦森与阿努诺比联手轰分，单节狂砍42分、净胜18分，半场反超7分 。- 第三节（35-27）：马刺调整节奏，尚帕尼、福克斯外线开火，文班亚马攻防一体，单节净胜8分，重夺领先优势。- 末节（23-20）：双方陷入胶着，布伦森连续高难度得分续命，阿努诺比三分追至2分；关键时刻卡斯尔命中关键三分，终场前两罚全中锁定胜局，尼克斯最后一攻未果。 核心球员数据 马刺（1-2） - 文班亚马：32分8篮板6助攻2抢断3盖帽，攻防全能，末节统治级表现。- 卡斯尔：23分5篮板5助攻，关键三分+致胜罚球，全场最佳奇兵。- 哈珀：13分9篮板4助攻；福克斯：12分8助攻；尚帕尼：12分；瓦塞尔：11分，六人得分上双。 尼克斯（2-1） - 布伦森：32分5篮板5助攻，全场最高分，末节独砍12分难救主。- 阿努诺比：28分5篮板；哈特：16分9篮板5助攻；唐斯：11分8篮板。 赛后要点 1. 马刺终结尼克斯季后赛13连胜（NBA季后赛历史第二长），避免0-3落后（NBA历史无球队能逆转此绝境） 。2. 文班亚马生涯总决赛首胜，32分追平个人季后赛得分纪录，攻防两端压制对手内线 。3. 总决赛G4将于6月11日继续在尼克斯主场进行，马刺有望乘势追平大比分。', 1781015234, '2026-06-09 14:27:14+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307904173540879', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (40, '7998579335', '小何同學Anny', 'https://tvax3.sinaimg.cn/crop.0.0.300.300.180/008JjdS7ly8i18euadsfkj308c08cwej.jpg?KID=imgbed,tva&Expires=1780997506&ssig=83NCFHehV8', 'f', 'https://m.weibo.cn/u/7998579335?launchid=10000360-page_H5', '浙江', 1780986841309, 1780986841309, 5307904136840805, '特朗普成为首位出席NBA总决赛的在任美国总统！#特朗普# 小何同學Anny的微博视频 ', 1781015225, '2026-06-09 14:27:05+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307904136840805', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (41, '6373621823', '婧候佳赫z', 'https://tvax3.sinaimg.cn/crop.0.0.1080.1080.180/006Xl4bZly8idyyanq78uj30u00u077z.jpg?KID=imgbed,tva&Expires=1780997620&ssig=os9Y9EMLSK', 'f', 'https://m.weibo.cn/u/6373621823?launchid=10000360-page_H5', '河南', 1780986841319, 1780986841333, 5307903970116931, 'G3这场球看得人血压飙升又忍不住拍案叫绝。马刺115-111硬生生从麦迪逊花园抢回一城，把大比分扳成1-2，尼克斯季后赛13连胜的金身也就此破了。文班亚马这表现真的没话说，32分8板6助2断3帽，攻防两端存在感拉满，关键时刻那几下处理球越来越有大将风范了。福克斯虽然投篮手感一般，但最后那记中距离杀 ...全文', 1781015185, '2026-06-09 14:26:25+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903970116931', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (42, '5605567446', '皮球画个C', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/0067moaaly8icp0gxbgv3j30u00u00xg.jpg?KID=imgbed,tva&Expires=1780997634&ssig=cVujngwV9g', 'm', 'https://m.weibo.cn/u/5605567446?luicode=20000061&lfid=5307903856608208&launchid=10000360-page_H5', '广东', 1780986841327, 1780986841327, 5307903856608208, '🏀争议判罚引爆总决赛！NBA总决赛G3，马刺115比111击败尼克斯，将系列赛大比分追至1比2。但赛后最受关注的话题，却是布伦森的一次防守动作。第三节比赛中，尚帕尼命中三分后落地踩到布伦森脚部，裁判经过录像回看后，将普通犯规升级为一级恶意犯规。这个判罚瞬间引发现场巨大争议，麦迪逊广场花园嘘声四起。不少尼克斯球迷认为，布伦森当时已经提前站定位置，防守动作并不存在明显恶意，升级恶犯的尺度过于严厉。与此同时，上半场文班亚马一次身体对抗动作却未被追加处罚，也让外界对判罚标准是否统一产生质疑。虽然联盟近年来对于侵占落地空间的危险动作始终保持高压态势，但这次吹罚依旧成为赛后讨论焦点。随着总决赛竞争愈发激烈，关于裁判尺度的争论恐怕还将持续发酵。#布伦森一级恶意犯规##NBA总决赛#', 1781015158, '2026-06-09 14:25:58+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307903856608208', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (43, '1671109627', '包容万物恒河水', 'https://tvax4.sinaimg.cn/crop.0.0.512.512.180/639b1bfbly8h0ikpj331kj20e80e8t8w.jpg?KID=imgbed,tva&Expires=1780997620&ssig=aEUtTUGayp', 'f', 'https://m.weibo.cn/u/1671109627?launchid=10000360-page_H5', '四川', 1780986841344, 1780986841344, 5307876048375321, '🔻特朗普从开场到离开，纽约人都在嘘他。🔻via MeidasTouch#特朗普看NBA总决赛睡着了##马刺1比2尼克斯##海外新鲜事##热点现场# ', 1781008528, '2026-06-09 12:35:28+08:00', '84', '8', '1', 'https://m.weibo.cn/detail/5307876048375321', 'NBA总决赛');
INSERT INTO `weibo_note` VALUES (44, '1699432410', '新华社', 'https://tvax2.sinaimg.cn/crop.58.61.875.875.180/001R0E0aly8h8vg6xx3srj60rs0rsdko02.jpg?KID=imgbed,tva&Expires=1780997816&ssig=02f%2FOJL9NR', 'm', 'https://m.weibo.cn/u/1699432410?luicode=20000061&lfid=5307493695619113&launchid=10000360-page_H5', '', 1780987054655, 1780987054655, 5307493695619113, '#习近平这样阐述发展中朝关系#【金句海报 | 习近平总书记在署名文章中这样阐述发展中朝关系】6月8日，在赴平壤对朝鲜民主主义人民共和国进行国事访问之际，中共中央总书记、国家主席习近平在朝鲜《劳动新闻》发表题为《继往开来、砥砺同行　续写中朝传统友谊崭新篇章》的署名文章，这样阐述发展中朝关系。#习近平在朝鲜媒体发表署名文章#', 1780917367, '2026-06-08 11:16:07+08:00', '262', '20', '73', 'https://m.weibo.cn/detail/5307493695619113', '中朝关系');
INSERT INTO `weibo_note` VALUES (45, '2656274875', '央视新闻', 'https://tvax4.sinaimg.cn/crop.0.0.690.690.180/002TLsr9ly8iakuy3heb6j60j60j6wex02.jpg?KID=imgbed,tva&Expires=1780997820&ssig=d6XFbOXIb%2F', 'm', 'https://m.weibo.cn/u/2656274875?luicode=20000061&lfid=5307594860398649&launchid=10000360-page_H5', '', 1780987054676, 1780987054676, 5307594860398649, '#习近平强调3个不会改变#【#中朝关系的鲜明特征#】#习近平同金正恩举行会谈# 当地时间6月8日下午，中共中央总书记、国家主席习近平在平壤锦绣山迎宾馆同朝鲜劳动党总书记、国务委员长金正恩举行会谈。习近平强调，中朝两国同为共产党领导的社会主义国家。中朝传统友谊植根于双方共同的理想信念和奋斗目标，有深厚历史积淀、坚实政治基础、牢固情感纽带，世代友好、命运与共、守望相助始终是中朝关系的鲜明特征。无论国际形势如何变化，中国党和政府高度重视中朝传统友好的坚定立场不会改变，对金正恩总书记同志领导朝鲜社会主义事业的坚定支持不会改变，维护中朝双方共同利益和良好战略环境的坚定决心不会改变。网页链接 央视新闻的微博视频', 1780941488, '2026-06-08 17:58:08+08:00', '2597', '171', '367', 'https://m.weibo.cn/detail/5307594860398649', '中朝关系');
INSERT INTO `weibo_note` VALUES (46, '1699432410', '新华社', 'https://tvax2.sinaimg.cn/crop.58.61.875.875.180/001R0E0aly8h8vg6xx3srj60rs0rsdko02.jpg?KID=imgbed,tva&Expires=1780997824&ssig=m2r6n4brAv', 'm', 'https://m.weibo.cn/u/1699432410?luicode=20000061&lfid=5307591313589852&launchid=10000360-page_H5', '', 1780987054691, 1780987054691, 5307591313589852, '#习近平同金正恩在平壤会谈#【习近平同金正恩举行会谈】#习近平就发展中朝关系提出4点意见# 当地时间6月8日下午，中共中央总书记、国家主席习近平在平壤锦绣山迎宾馆同朝鲜劳动党总书记、国务委员长金正恩举行会谈。　　习近平指出，时隔7年再次到访美丽的平壤，我感到十分高兴，也格外亲切。我愿同总书记同志一道，以这次访问为契机，加强对新时期中朝关系的顶层设计和战略指引，推动中朝关系与时俱进、得到更大发展，更好造福两国和两国人民，为地区乃至世界和平稳定和发展繁荣作出积极贡献。　　习近平强调，中朝两国同为共产党领导的社会主义国家。中朝传统友谊植根于双方共同的理想信念和奋斗目标，有深厚历史积淀、坚实政治基础、牢固情感纽带，世代友好、命运与共、守望相助始终是中朝关系的鲜明特征。无论国际形势如何变化，中国党和政府高度重视中朝传统友好的坚定立场不会改变，对金正恩总书记同志领导朝鲜社会主义事业的坚定支持不会改变，维护中朝双方共同利益和良好战略环境的坚定决心不会改变。　　习近平指出，面对加速演进的世界百年变局，双方要登高望远、继往开来，从两党两国关系发展历程中汲取智慧，在人类历史发展大势中把握机遇，为中朝传统友谊注入新的时代内涵和强劲动力，开辟两国社会主义事业和地区和平与发展更加美好的前景。　　习近平就发展中朝关系提出4点意见。　　第一，坚持以高层交往为引领，夯实政治互信根基。最高领导人战略引领是中朝关系的最大优势。我愿同总书记同志保持密切战略沟通，引领中朝关系不断迈向新高度。今年是《中朝友好合作互助条约》签订65周年，双方要隆重举办纪念活动。两党关系对中朝关系发展发挥重要引领作用，要进一步拓展和活跃两党各层级各领域友好交往，深化治党治国经验交流互鉴。双方要加强外交、执法、军队等交流，落实好我和总书记同志达成的重要共识，为中朝关系发展汇聚智慧和力量。　　第二，坚持以为民造福为目标，提升务实合作水平。中方愿同朝方加强发展战略对接，扩大经贸、农业、建筑、科技、医疗卫生等务实合作，更好造福两国人民。双方要以边境口岸全面复通、民航航班和国际客运列车恢复运营为契机，扩大人员往来，实现双向奔赴。　　第三，坚持以友谊传承为动力，拉紧民心相通纽带。中朝用鲜血凝成的传统友谊是两国人民共同的宝贵财富。中方愿同朝方一道，共同维护好、管理好在朝志愿军烈士纪念设施，开展富有特色的革命传统教育、青少年思想教育，传承好两国红色基因和传统友谊。中方愿同朝方用好各自优势资源，加强教育、文艺、旅游、体育、媒体、青年、地方、友城等交流合作，让中朝传统友谊更加深入人心。　　第四，坚持以公平正义为理念，丰富战略协作内涵。面对人类向何处去这一重大课题，我提出构建人类命运共同体理念和四大全球倡议，希望推动全球治理朝着更加公正合理的方向发展，得到包括朝方在内的国际社会广泛支持和积极响应。亚洲是中朝等地区国家的安身立命之所。中朝两国应加强战略协调和配合，坚定捍卫各自主权、安全、发展利益，共同维护地区和平与发展。　　金正恩表示，习近平总书记同志时隔7年再次访问朝鲜，是朝鲜人民最尊重的贵宾，我们表示最隆重、最热烈的欢迎。习近平总书记今年首次出访就来到平壤，体现了对朝中关系的高度重视和友好情谊，对朝方是莫大的鼓舞。此访再次清晰表明，久经考验的、始终站在自主和正义的历史正确一边的朝中关系是多么牢不可破。朝中两国的特殊性不仅在于我们互为邻国，更在于双方具有深厚传统友谊和共同的理想信念，并对此彼此珍视和代代传承。　　金正恩表示，去年9月我同习近平总书记在北京会晤后，两国关系在各领域活跃发展，给两国人民带来实实在在的福祉。由衷感谢习近平总书记同志就新时代朝中关系发展提出的重要意见，朝方各部门将同中方同志一道全力以赴全面落实，推动双方在经贸、基础设施、科技、教育、人文等广泛领域的交流合作取得新发展，通过党际渠道加强经验交流互鉴为朝方社会主义建设事业发展提供宝贵助力，帮助朝鲜人民同中国人民一道迈向现代化之路。　　金正恩表示，朝方高兴地看到，在习近平总书记同志领导下，中国取得令世界惊叹的发展成就，国际地位极大提升。习近平总书记提出的人类命运共同体理念和四大全球倡议对促进世界和平与发展具有深远意义，得到世界人民的支持和赞赏。近年来国际社会正经历前所未有的巨大变化，朝方将始终不渝地坚持一个中国原则，坚定支持中国维护核心利益的政策和立场。巩固和发展新时代朝中友谊是人民的选择、时代的需要，是朝方始终不变的战略选择和坚定不移的战略意志。我们会一如既往将发展朝中关系作为国家最重大的第一战略事业，为把朝中关系建设成国家关系的典范而竭尽全力，共同为地区和世界的和平繁荣作出贡献。　　蔡奇、王毅等参加会谈。#习近平朝鲜之行#  新华社的微博视频', 1780940642, '2026-06-08 17:44:02+08:00', '3545', '380', '587', 'https://m.weibo.cn/detail/5307591313589852', '中朝关系');
INSERT INTO `weibo_note` VALUES (47, '2803301701', '人民日报', 'https://tvax4.sinaimg.cn/crop.0.0.1018.1018.180/0033ImPzly8h8vgemh8kxj60sa0sadgw02.jpg?KID=imgbed,tva&Expires=1780997828&ssig=ZT2covjYJr', 'm', 'https://m.weibo.cn/u/2803301701?luicode=20000061&lfid=5307548397208418&launchid=10000360-page_H5', '', 1780987054704, 1780987054704, 5307548397208418, '【此行间·#从这些瞬间感受中朝友谊#】#朝鲜民众沿途欢迎现场# 在礼宾摩托车队的护卫下，习近平总书记乘车前往金日成广场。沿途民众挥舞着中朝两国国旗，手持五彩缤纷的鲜花，高举欢迎标语，热情迎接习近平总书记的到访。期待中朝最高领导人共话中朝传统友谊，共商中朝关系发展大计。#习近平总书记朝鲜之行# 人民日报的微博视频', 1780930410, '2026-06-08 14:53:30+08:00', '1667', '132', '123', 'https://m.weibo.cn/detail/5307548397208418', '中朝关系');
INSERT INTO `weibo_note` VALUES (48, '1784473157', '中国新闻网', 'https://tvax3.sinaimg.cn/crop.0.0.300.300.180/001WLsZ7ly8h8vgjl2u01j608c08caa302.jpg?KID=imgbed,tva&Expires=1780997814&ssig=UI13xjX%2BR4', 'm', 'https://m.weibo.cn/u/1784473157?launchid=10000360-page_H5', '', 1780987054711, 1780987054711, 5307649445072400, '#习言道#【#让中朝传统友谊更加深入人心#】当地时间6月8日，中共中央总书记、国家主席习近平在平壤锦绣山迎宾馆同朝鲜劳动党总书记、国务委员长金正恩举行会谈。习近平指出—— ', 1780954502, '2026-06-08 21:35:02+08:00', '80', '3', '18', 'https://m.weibo.cn/detail/5307649445072400', '中朝关系');
INSERT INTO `weibo_note` VALUES (49, '1893892941', '北京日报', 'https://tvax4.sinaimg.cn/crop.0.0.600.600.180/0024aA4lly8i51bp1z4bcj60go0goq3g02.jpg?KID=imgbed,tva&Expires=1780997832&ssig=7xF9PhYe7P', 'm', 'https://m.weibo.cn/u/1893892941?luicode=20000061&lfid=5307557591125760&launchid=10000360-page_H5', '', 1780987054718, 1780987054718, 5307557591125760, '#外交部回应对朝鲜半岛问题立场#【外交部：中方在半岛问题上的立场和政策保持连续性、稳定性】6月8日，外交部发言人林剑主持例行记者会。法新社记者就中方对朝鲜半岛问题的立场进行提问。林剑表示，中方在半岛问题上的立场和政策保持连续性、稳定性。关于习近平主席对朝鲜进行国事访问，我们会适时发布消息，请你继续保持关注。（@北京日报 记者 刘晓琰）戳更多新闻→#中朝关系的鲜明特征# 北京日报的微博视频', 1780932602, '2026-06-08 15:30:02+08:00', '88', '6', '34', 'https://m.weibo.cn/detail/5307557591125760', '中朝关系');
INSERT INTO `weibo_note` VALUES (50, '2280198017', '解放军报', 'https://tvax3.sinaimg.cn/crop.12.21.1059.1059.180/002ujtFnly8h8vga88q7gj60u00u0juh02.jpg?KID=imgbed,tva&Expires=1780997836&ssig=dBRrRu%2FmRE', 'm', 'https://m.weibo.cn/u/2280198017?luicode=20000061&lfid=5307418143621737&launchid=10000360-page_H5', '', 1780987054726, 1780987054726, 5307418143621737, '【习近平在朝鲜媒体发表署名文章】6月8日，在赴平壤对朝鲜民主主义人民共和国进行国事访问之际，中共中央总书记、国家主席习近平在朝鲜《劳动新闻》发表题为《继往开来、砥砺同行　续写中朝传统友谊崭新篇章》的署名文章。文章全文如下：　　继往开来、砥砺同行　　续写中朝传统友谊崭新篇章　　中共中央总书记、中华人民共和国主席　习近平　　今年是《中朝友好合作互助条约》签订65周年。应朝鲜劳动党总书记、国务委员长金正恩同志邀请，我即将对朝鲜进行国事访问。这是我时隔7年再次访问美丽的朝鲜。我期待同金正恩总书记共话中朝传统友谊，共商中朝关系发展大计。　　中朝两国是守望相助、命运与共的社会主义友好邻邦。中朝传统友谊是两党两国和两国人民共同的宝贵财富。无论时代如何变迁、国际形势如何变化，中朝传统友谊始终牢不可破、历久弥坚，不断焕发蓬勃生机活力。　　最高层战略引领是中朝关系的最大优势。历史上，中朝老一辈领导人相交相知、亲密无间。近年来，我同金正恩总书记6次会晤，保持密切战略沟通，共同擘画中朝关系发展蓝图。我坚信，中朝关系这艘航船有最高领导人领航掌舵，必将乘风破浪、勇往直前。　　社会主义共同理想是中朝关系的鲜明底色。中国共产党和朝鲜劳动党同为马克思主义执政党，中朝两国是社会主义道路上的同行者。我坚信，两党两国携手推动各自党和国家事业发展，持续加强务实交流合作，必将有力促进国家繁荣富强和人民幸福安康，不断彰显社会主义的显著优势和光明前景。　　命运与共的传统友谊是中朝关系的深厚根基。在争取国家独立和民族解放的峥嵘岁月中，中朝两国人民休戚与共、生死相依，用鲜血凝结了伟大的战斗友谊。在各自社会主义事业发展中，两国人民携手并肩、同甘共苦，生动诠释了彼此信赖、团结互助的同志情谊。我坚信，历经时代变迁和国际风云变幻考验的中朝传统友谊，必将薪火相传、万古长青。　　高水平战略协作是中朝关系的时代内涵。促进地区长治久安、世界和平稳定是两党两国和两国人民的共同追求。双方坚定支持彼此维护国家主权、安全、发展利益，携手维护地区和平安宁、国际公平正义和战后国际秩序。我坚信，中朝双方持续深化战略协作，必将共同走好和平发展、合作共赢的人间正道。　　近年来，面对加速演进的世界百年变局和变乱交织的国际形势，中朝双方坚持集中精力办好自己的事，在社会主义道路上砥砺前行、不懈奋斗。中国实现“十五五”良好开局，正在奋力开创中国式现代化建设新局面，向着第二个百年奋斗目标阔步迈进。朝鲜劳动党胜利召开第九次代表大会，对朝鲜党和国家事业发展作出战略规划和重大部署，开启社会主义全面发展新时期。　　维护好、巩固好、发展好中朝关系始终是中国党和政府坚定不移的方针。当前，中朝关系站在新的历史起点，面临新的发展机遇，肩负新的时代使命。中方愿同朝方一道，从战略高度把握中朝关系，推动中朝关系与时俱进、得到更大发展。　　——深化战略沟通，牢牢把握中朝关系发展正确方向。我们要保持两党两国高层交往优良传统，像亲戚一样常来往、多走动。以《中朝友好合作互助条约》签订65周年为契机，加强党政军各部门各层级沟通交往，落实好双方重要共识，为中朝关系发展注入强劲动力。　　——加强交流互鉴，共同推动两国社会主义事业行稳致远。我们要坚持道不变、志不改，相互支持彼此走符合自身国情的社会主义道路，坚定维护两国政治安全。坚持和加强党的全面领导，拓展两党交往合作，深化治党治国经验交流互鉴，引领两国社会主义事业不断从胜利走向胜利。　　——拓展务实合作，持续增进两国人民福祉和友谊。我们要加强两国发展战略对接，挖掘各领域合作潜力，共享机遇，共促发展，更好惠及两国人民。通过灵活多样的形式，持续活跃友好往来，深化相互了解，拉紧情感纽带，把中朝友好的接力棒一代一代传下去。　　——密切多边协作，坚定捍卫国际公平正义。我们要顺应时代潮流，加强战略沟通和协调配合，共同维护以联合国为核心的国际体系和以国际法为基础的国际秩序，反对霸权主义和强权政治，反对一切复活军国主义、危害地区安全稳定的图谋和行径。共同推进平等有序的世界多极化、普惠包容的经济全球化，落实四大全球倡议，携手推动构建人类命运共同体。　　岁月共磨砺，烈火见真金。我们愿同朝鲜同志携手前行、续写新篇，让中朝传统友谊焕发更加璀璨的时代光辉，为促进地区乃至世界和平稳定和发展繁荣作出更大贡献。#军报快讯# （新华社）央视新闻的微博视频', 1780899355, '2026-06-08 06:15:55+08:00', '65', '1', '13', 'https://m.weibo.cn/detail/5307418143621737', '中朝关系');
INSERT INTO `weibo_note` VALUES (51, '2821669511', '农民日报', 'https://tvax3.sinaimg.cn/crop.0.0.512.512.180/a82f4287ly8h8vgozf793j20e80e874h.jpg?KID=imgbed,tva&Expires=1780997814&ssig=JElMEis4uu', 'm', 'https://m.weibo.cn/u/2821669511?launchid=10000360-page_H5', '', 1780987054733, 1780987054733, 5307626680484628, '习近平同金正恩举行会谈 农民日报的微博视频 ', 1780949074, '2026-06-08 20:04:34+08:00', '137', '4', '12', 'https://m.weibo.cn/detail/5307626680484628', '中朝关系');
INSERT INTO `weibo_note` VALUES (52, '6244553417', '今日俄罗斯RT', 'https://tvax2.sinaimg.cn/crop.0.0.600.600.180/006OBvBvly8id2elooulrj30go0goglu.jpg?KID=imgbed,tva&Expires=1780997840&ssig=X31jo%2FvjOV', 'm', 'https://m.weibo.cn/u/6244553417?luicode=20000061&lfid=5307621206659198&launchid=10000360-page_H5', '', 1780987054740, 1780987054740, 5307621206659198, '【#习近平同金正恩举行会谈#】6月8日，中共中央总书记、中国国家主席习近平在访问平壤时同朝鲜劳动党总书记、国务委员长金正恩举行会谈。习近平表示，愿以这次访问为契机，加强对新时期中朝关系的顶层设计和战略指引，推动中朝关系与时俱进、得到更大发展，更好造福两国和两国人民，为地区乃至世界和平稳定和发展繁荣作出积极贡献。习近平强调，中朝传统友谊植根于双方共同的理想信念和奋斗目标，有深厚历史积淀、坚实政治基础、牢固情感纽带，世代友好、命运与共、守望相助始终是中朝关系的鲜明特征。中方愿同朝方加强发展战略对接，扩大经贸、农业、建筑、科技、医疗卫生等务实合作，更好造福两国人民。 今日俄罗斯RT的微博视频', 1780947769, '2026-06-08 19:42:49+08:00', '50', '5', '4', 'https://m.weibo.cn/detail/5307621206659198', '中朝关系');
INSERT INTO `weibo_note` VALUES (53, '2512851283', '忻州新闻', 'https://tvax4.sinaimg.cn/crop.0.0.600.600.180/95c71153ly8h8vgg5o8bej20go0got9r.jpg?KID=imgbed,tva&Expires=1780997814&ssig=cK15jPhdK2', 'm', 'https://m.weibo.cn/u/2512851283?launchid=10000360-page_H5', '', 1780987054752, 1780987054752, 5307555876438972, '近闻·总书记这样讲述中朝友谊网页链接 ', 1780932193, '2026-06-08 15:23:13+08:00', '2', '0', '1', 'https://m.weibo.cn/detail/5307555876438972', '中朝关系');
INSERT INTO `weibo_note` VALUES (54, '2252846093', '长春新闻', 'https://tvax4.sinaimg.cn/crop.0.0.995.995.180/8647b40dly8h8vg7360c9j20rn0rn0up.jpg?KID=imgbed,tva&Expires=1780997844&ssig=5t9T4W3Q4Y', 'f', 'https://m.weibo.cn/u/2252846093?luicode=20000061&lfid=5307906267810557&launchid=10000360-page_H5', '', 1780987054760, 1780987054760, 5307906267810557, '#中朝最高领导人握手合影#【此行间·现场画面！#习近平和金正恩种下一株枞树#】习近平总书记和金正恩总书记共同执锹培土、提水浇灌，种下一株枞树。枞树四季常绿，象征中朝友谊生生不息。7年前，习近平总书记曾以“参天大树”生动比喻中朝关系。“中朝友谊万古长青”！#常绿枞树象征中朝友谊生生不息# 人民日报的微博视频', 1781015733, '2026-06-09 14:35:33+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307906267810557', '中朝关系');
INSERT INTO `weibo_note` VALUES (55, '1938330147', '外交部', 'https://tvax4.sinaimg.cn/crop.0.0.443.443.180/0027b2dtly8gzu9xar39hj60cb0cbmx202.jpg?KID=imgbed,tva&Expires=1780997848&ssig=Ke9sVSTvA%2B', 'f', 'https://m.weibo.cn/u/1938330147?luicode=20000061&lfid=5307905982857457&launchid=10000360-page_H5', '', 1780987054768, 1780987054768, 5307905982857457, '【#习近平参访朝鲜劳动党中央干部学校#】当地时间2026年6月9日上午，中共中央总书记、国家主席习近平在朝鲜劳动党总书记、国务委员长金正恩陪同下，参访位于平壤的朝鲜劳动党中央干部学校。11时许，习近平乘车抵达。金正恩在学校标志性建筑朝鲜劳动党象征塔前迎接。数百名师生夹道欢迎，师生代表向习近平献上鲜花。在金正恩陪同下，习近平步入学校阶梯教室。教室内学员整齐端坐，教员正在讲授朝鲜对外关系课程中有关中朝关系的内容。中朝两党总书记到来时，师生们一起站立，向两党总书记报以热烈的掌声。习近平和金正恩驻足观摩授课，不时颔首赞许。离开阶梯教室后，习近平和金正恩乘坐电瓶车参观校园，沿途听取有关学校基础设施、教学安排等介绍。来到教学楼之间的林地上，习近平和金正恩共同执锹培土、提水浇灌，种下一株枞树。枞树四季常绿，象征中朝友谊生生不息。随后，在两党两国最高领导人见证下，蔡奇和朝鲜劳动党中央政治局常委、中央书记金才龙共同为植树标识碑揭幕。碑身正面，用中朝双语镌刻着“中朝友谊万古长青”几个大字。在双方陪同人员和朝方学员们的热烈掌声中，习近平和金正恩在植树标识碑前握手合影。蔡奇、王毅等参加上述活动。#元首外交##跟我看外交#', 1781015665, '2026-06-09 14:34:25+08:00', '3', '0', '0', 'https://m.weibo.cn/detail/5307905982857457', '中朝关系');
INSERT INTO `weibo_note` VALUES (56, '3869200206', '抚松发布', 'https://tvax1.sinaimg.cn/crop.2.0.175.175.180/e69f4f4ely8h8vh22bibzj2050050q2x.jpg?KID=imgbed,tva&Expires=1780997814&ssig=2tfUhu7063', 'f', 'https://m.weibo.cn/u/3869200206?launchid=10000360-page_H5', '', 1780987054775, 1780987054775, 5307904926156134, '#中朝最高领导人会谈有这些关键词##朝鲜欢迎最尊重的贵宾#当地时间 6 月 8 日下午，习近平主席在平壤锦绣山迎宾馆同朝鲜劳动党总书记、国务委员长金正恩举行会谈，双方共叙传统友谊、共商合作大计，为新时期中朝关系发展擘画蓝图。网页链接 ', 1781015413, '2026-06-09 14:30:13+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307904926156134', '中朝关系');
INSERT INTO `weibo_note` VALUES (57, '7811118539', '大公報', 'https://tvax1.sinaimg.cn/crop.0.0.600.600.180/008wCEKTly8h9lxo8okhcj30go0gowex.jpg?KID=imgbed,tva&Expires=1780997852&ssig=YWbsfkuHe%2B', 'm', 'https://m.weibo.cn/u/7811118539?luicode=20000061&lfid=5307904824708729&launchid=10000360-page_H5', '', 1780987054783, 1780987054783, 5307904824708729, '【出席金正恩举行的欢迎宴会 强调两国命运与共 习近平：拓展中朝务实合作 增进民心相通】当地时间6月8日晚，中共中央总书记、国家主席习近平和夫人彭丽媛在平壤木兰馆出席朝鲜劳动党总书记、国务委员长金正恩举行的欢迎宴会。在前往木兰馆的路上，沿途站满身着民族盛装的热情民众，热烈欢迎习近平的车队经过。木兰馆宴会厅张灯结彩、鲜花吐蕊，洋溢着喜庆热烈的氛围。晚7时许，习近平和彭丽媛抵达木兰馆，金正恩和夫人李雪主热情迎接。两党两国最高领导人夫妇亲切合影。朝鲜党和国家领导人列队欢迎致敬。随后，习近平和彭丽媛在金正恩和李雪主陪同下步入宴会大厅。全场人员起立欢迎。在热烈的掌声中，习近平和金正恩分别发表致辞。习近平指出，中朝两国山水相连、命运与共，中朝传统友谊在国际风云变幻的考验中薪火相传、历久弥坚。今年是《中朝友好合作互助条约》签订65周年，中朝关系站在新的历史起点上。我这次访问，同金正恩总书记达成重要共识。我们一致认为，要从社会主义前途命运的战略高度，把握时代大势，顺应两国人民共同愿望，加强高层交往，深化战略沟通，拓展务实合作，增进民心相通，推动中朝关系高水平发展，携手开辟两国社会主义事业更加美好的前景，促进人类社会不断进步。习近平表示，今年，朝鲜劳动党九大胜利召开，对朝鲜党和国家事业长远发展作出战略规划和重大部署，开启朝鲜社会主义全面发展新时期。作为好邻居、好朋友、好同志，中方衷心祝愿在以金正恩总书记为首的朝鲜劳动党中央坚强领导下，朝鲜人民顺利完成朝鲜劳动党九大提出的目标任务，推动朝鲜社会主义事业不断开创新局面。金正恩代表朝鲜党、政府和人民，对习近平到访表示最诚挚的欢迎。金正恩表示，今天的平壤到处洋溢着友好情谊，热烈欢迎朝鲜党、政府和人民最尊贵的客人。习近平总书记今年首次出访即来到朝鲜，彰显对发展朝中两党两国关系的高度重视和对朝鲜社会主义事业的最宝贵支持。金正恩表示，我与习近平总书记同志时隔9个月再次会晤，就结合新的形势变化进一步推进具有新的时代内涵的朝中关系达成重要共识，并就共同关心的国际和地区问题广泛交换意见，必将推动具有深厚历史传统的朝中友谊加速向前发展，为地区和世界的和平稳定作出贡献。朝鲜人民对兄弟的中国人民所取得的伟大成就由衷感到高兴，相信在以习近平总书记同志为核心的中国共产党领导下，伟大的中国人民必将在全面建设社会主义现代化强国、实现第二个百年奋斗目标、实现中华民族伟大复兴新征程中创造更大成就。蔡奇、王毅等出席宴会。#中朝友谊##习近平访朝##金正恩欢迎宴会##命运与共##务实合作#', 1781015389, '2026-06-09 14:29:49+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307904824708729', '中朝关系');
INSERT INTO `weibo_note` VALUES (58, '2821669511', '农民日报', 'https://tvax3.sinaimg.cn/crop.0.0.512.512.180/a82f4287ly8h8vgozf793j20e80e874h.jpg?KID=imgbed,tva&Expires=1780997814&ssig=JElMEis4uu', 'm', 'https://m.weibo.cn/u/2821669511?launchid=10000360-page_H5', '', 1780987054791, 1780987054791, 5307831902278672, '习近平：时隔七年再次到访美丽的平壤 我感到十分高兴 也格外亲切 农民日报的微博视频 ', 1780998003, '2026-06-09 09:40:03+08:00', '132', '2', '13', 'https://m.weibo.cn/detail/5307831902278672', '中朝关系');
INSERT INTO `weibo_note` VALUES (59, '3937348351', '共青团中央', 'https://tvax4.sinaimg.cn/crop.0.0.600.600.180/004isIazly8ht9hper28ej60go0got9m02.jpg?KID=imgbed,tva&Expires=1780998159&ssig=v1%2Fbkq%2F4YJ', 'm', 'https://m.weibo.cn/u/3937348351?luicode=20000061&lfid=5307651101820068&launchid=10000360-page_H5', '', 1780987390826, 1780987390826, 5307651101820068, '【#习近平同金正恩举行会谈#】当地时间6月8日下午，中共中央总书记、国家主席习近平在平壤锦绣山迎宾馆同朝鲜劳动党总书记、国务委员长金正恩举行会谈。习近平指出，时隔7年再次到访美丽的平壤，我感到十分高兴，也格外亲切。我愿同总书记同志一道，以这次访问为契机，加强对新时期中朝关系的顶层设计和战略指引，推动中朝关系与时俱进、得到更大发展，更好造福两国和两国人民，为地区乃至世界和平稳定和发展繁荣作出积极贡献。习近平强调，中朝两国同为共产党领导的社会主义国家。中朝传统友谊植根于双方共同的理想信念和奋斗目标，有深厚历史积淀、坚实政治基础、牢固情感纽带，世代友好、命运与共、守望相助始终是中朝关系的鲜明特征。无论国际形势如何变化，中国党和政府高度重视中朝传统友好的坚定立场不会改变，对金正恩总书记同志领导朝鲜社会主义事业的坚定支持不会改变，维护中朝双方共同利益和良好战略环境的坚定决心不会改变。习近平指出，面对加速演进的世界百年变局，双方要登高望远、继往开来，从两党两国关系发展历程中汲取智慧，在人类历史发展大势中把握机遇，为中朝传统友谊注入新的时代内涵和强劲动力，开辟两国社会主义事业和地区和平与发展更加美好的前景。习近平就发展中朝关系提出4点意见。第一，坚持以高层交往为引领，夯实政治互信根基。最高领导人战略引领是中朝关系的最大优势。我愿同总书记同志保持密切战略沟通，引领中朝关系不断迈向新高度。今年是《中朝友好合作互助条约》签订65周年，双方要隆重举办纪念活动。两党关系对中朝关系发展发挥重要引领作用，要进一步拓展和活跃两党各层级各领域友好交往，深化治党治国经验交流互鉴。双方要加强外交、执法、军队等交流，落实好我和总书记同志达成的重要共识，为中朝关系发展汇聚智慧和力量。第二，坚持以为民造福为目标，提升务实合作水平。中方愿同朝方加强发展战略对接，扩大经贸、农业、建筑、科技、医疗卫生等务实合作，更好造福两国人民。双方要以边境口岸全面复通、民航航班和国际客运列车恢复运营为契机，扩大人员往来，实现双向奔赴。第三，坚持以友谊传承为动力，拉紧民心相通纽带。中朝用鲜血凝成的传统友谊是两国人民共同的宝贵财富。中方愿同朝方一道，共同维护好、管理好在朝志愿军烈士纪念设施，开展富有特色的革命传统教育、青少年思想教育，传承好两国红色基因和传统友谊。中方愿同朝方用好各自优势资源，加强教育、文艺、旅游、体育、媒体、青年、地方、友城等交流合作，让中朝传统友谊更加深入人心。第四，坚持以公平正义为理念，丰富战略协作内涵。面对人类向何处去这一重大课题，我提出构建人类命运共同体理念和四大全球倡议，希望推动全球治理朝着更加公正合理的方向发展，得到包括朝方在内的国际社会广泛支持和积极响应。亚洲是中朝等地区国家的安身立命之所。中朝两国应加强战略协调和配合，坚定捍卫各自主权、安全、发展利益，共同维护地区和平与发展。金正恩表示，习近平总书记同志时隔7年再次访问朝鲜，是朝鲜人民最尊重的贵宾，我们表示最隆重、最热烈的欢迎。习近平总书记今年首次出访就来到平壤，体现了对朝中关系的高度重视和友好情谊，对朝方是莫大的鼓舞。此访再次清晰表明，久经考验的、始终站在自主和正义的历史正确一边的朝中关系是多么牢不可破。朝中两国的特殊性不仅在于我们互为邻国，更在于双方具有深厚传统友谊和共同的理想信念，并对此彼此珍视和代代传承。金正恩表示，去年9月我同习近平总书记在北京会晤后，两国关系在各领域活跃发展，给两国人民带来实实在在的福祉。由衷感谢习近平总书记同志就新时代朝中关系发展提出的重要意见，朝方各部门将同中方同志一道全力以赴全面落实，推动双方在经贸、基础设施、科技、教育、人文等广泛领域的交流合作取得新发展，通过党际渠道加强经验交流互鉴为朝方社会主义建设事业发展提供宝贵助力，帮助朝鲜人民同中国人民一道迈向现代化之路。金正恩表示，朝方高兴地看到，在习近平总书记同志领导下，中国取得令世界惊叹的发展成就，国际地位极大提升。习近平总书记提出的人类命运共同体理念和四大全球倡议对促进世界和平与发展具有深远意义，得到世界人民的支持和赞赏。近年来国际社会正经历前所未有的巨大变化，朝方将始终不渝地坚持一个中国原则，坚定支持中国维护核心利益的政策和立场。巩固和发展新时代朝中友谊是人民的选择、时代的需要，是朝方始终不变的战略选择和坚定不移的战略意志。我们会一如既往将发展朝中关系作为国家最重大的第一战略事业，为把朝中关系建设成国家关系的典范而竭尽全力，共同为地区和世界的和平繁荣作出贡献。蔡奇、王毅等参加会谈。央视新闻的微博视频', 1780954897, '2026-06-08 21:41:37+08:00', '716', '331', '70', 'https://m.weibo.cn/detail/5307651101820068', '中朝关系');
INSERT INTO `weibo_note` VALUES (60, '3604378011', '中国新闻社', 'https://tvax3.sinaimg.cn/crop.0.0.494.494.180/d6d6719bly8h8vggz3tlxj20dq0dq74s.jpg?KID=imgbed,tva&Expires=1780998163&ssig=45XMRoJNzv', 'm', 'https://m.weibo.cn/u/3604378011?luicode=20000061&lfid=5307902412986207&launchid=10000360-page_H5', '', 1780987390844, 1780987390844, 5307902412986207, '#近观中国#【习近平访朝提出四个“坚持”，推动中朝关系与时俱进】#习近平访朝提出四个坚持#“面对加速演进的世界百年变局，双方要登高望远、继往开来”，当地时间6月8日，中共中央总书记、国家主席习近平在平壤同朝鲜劳动党总书记、国务委员长金正恩会谈时如是说。应金正恩邀请，习近平于6月8日至9日对朝鲜进行国事访问。就发展中朝关系，习近平在会谈中提出四个“坚持”：坚持以高层交往为引领，夯实政治互信根基；坚持以为民造福为目标，提升务实合作水平；坚持以友谊传承为动力，拉紧民心相通纽带；坚持以公平正义为理念，丰富战略协作内涵。（记者 李晓喻 黄钰钦）习近平访朝提出四个“坚持”，推动中朝关系与时俱进', 1781014814, '2026-06-09 14:20:14+08:00', '0', '0', '1', 'https://m.weibo.cn/detail/5307902412986207', '中朝关系');
INSERT INTO `weibo_note` VALUES (61, '2803301701', '人民日报', 'https://tvax4.sinaimg.cn/crop.0.0.1018.1018.180/0033ImPzly8h8vgemh8kxj60sa0sadgw02.jpg?KID=imgbed,tva&Expires=1780998167&ssig=BJJ5xDzb0p', 'm', 'https://m.weibo.cn/u/2803301701?luicode=20000061&lfid=5307897737120186&launchid=10000360-page_H5', '', 1780987390855, 1780987390855, 5307897737120186, '#中朝最高领导人握手合影#【此行间·现场画面！#习近平和金正恩种下一株枞树#】习近平总书记和金正恩总书记共同执锹培土、提水浇灌，种下一株枞树。枞树四季常绿，象征中朝友谊生生不息。7年前，习近平总书记曾以“参天大树”生动比喻中朝关系。“中朝友谊万古长青”！#常绿枞树象征中朝友谊生生不息# 人民日报的微博视频', 1781013699, '2026-06-09 14:01:39+08:00', '550', '63', '40', 'https://m.weibo.cn/detail/5307897737120186', '中朝关系');
INSERT INTO `weibo_note` VALUES (62, '3042569007', '广州检察', 'https://tvax3.sinaimg.cn/crop.0.0.512.512.180/b559eb2fly8h8w53yjf9ej20e80e8wf3.jpg?KID=imgbed,tva&Expires=1780998171&ssig=uATQ9miYxq', 'm', 'https://m.weibo.cn/u/3042569007?luicode=20000061&lfid=5307901864576660&launchid=10000360-page_H5', '', 1780987390863, 1780987390863, 5307901864576660, '#推动中朝关系与时俱进#【独家视频 | 习近平：#时隔七年再次到访美丽的平壤# 我感到十分高兴 也格外亲切】当地时间6月8日下午，中共中央总书记、国家主席习近平在平壤锦绣山迎宾馆同朝鲜劳动党总书记、国务委员长金正恩举行会谈。#习近平同金正恩举行会谈#习近平指出，时隔7年再次到访美丽的平壤，我感到十分高兴，也格外亲切。我愿同总书记同志一道，以这次访问为契机，加强对新时期中朝关系的顶层设计和战略指引，推动中朝关系与时俱进、得到更大发展，更好造福两国和两国人民，为地区乃至世界和平稳定和发展繁荣作出积极贡献。金正恩说：“习近平总书记同志今年首次出访就来到平壤，体现了对朝中关系的高度重视和友好情谊，对朝方是莫大的鼓舞。我们认为，总书记同志此访再次清晰表明，朝中两国始终站在自主和正义的历史正确一边，并向世界彰显，无论国际形势如何风云变幻，久经考验的朝中关系是多么牢不可破。”（央视新闻）央视新闻的微博视频', 1781014683, '2026-06-09 14:18:03+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307901864576660', '中朝关系');
INSERT INTO `weibo_note` VALUES (63, '1682207150', '南方日报', 'https://tvax2.sinaimg.cn/crop.0.0.640.640.180/001PQmVoly8h8vgdozraej60hs0hs74y02.jpg?KID=imgbed,tva&Expires=1780998175&ssig=lJP5QPkIAH', 'm', 'https://m.weibo.cn/u/1682207150?luicode=20000061&lfid=5307843043133774&launchid=10000360-page_H5', '', 1780987390871, 1780987390871, 5307843043133774, '【读懂中朝关系“三个不会改变”】#习近平同金正恩在平壤会谈#6月8日至9日，中共中央总书记、国家主席习近平对朝鲜进行国事访问。“习近平总书记同志时隔7年再次访问朝鲜，是朝鲜人民最尊重的贵宾，我们表示最隆重、最热烈的欢迎。”朝鲜劳动党总书记、国务委员长金正恩高度评价习近平总书记此次访问，表示“对朝方是莫大的鼓舞”。今年是《中朝友好合作互助条约》签订65周年，两党两国最高领导人共话中朝传统友谊，共商中朝关系发展大计，为中朝携手建设社会主义事业注入强劲动力。#中朝最高领导人会谈有这些关键词# （一）中朝地缘相亲、文缘相通，各领域合作既有悠久传统，也有深厚潜能，是命运与共、守望相助的好邻居、好朋友、好同志。两国的传统友谊是中朝关系的深厚根基。1949年，中朝正式建立外交关系，掀开两国关系新的历史篇章。1961年，两国老一辈领导人高瞻远瞩，作出签订《中朝友好合作互助条约》的战略决策，为推动两国持久友好合作奠定了重要政治法律基础。回顾往昔，从共同反对外来侵略、争取国家独立和民族解放，到并肩开展社会主义革命和建设事业，中朝传统友谊始终牢不可破、历久弥坚。最高层战略引领是中朝关系的最大优势。从2018年3月的历史性首次会晤达成四方面原则共识，到金正恩总书记百日内三度访华、双方共同开创中朝高层交往新历史；从2019年半年内实现互访，到2025年9月再度相聚北京，再到这次习近平总书记历史性访朝……2018年以来，中朝两党两国最高领导人7次会晤，并以多种形式保持着密切沟通，引领推动中朝关系在新时代破浪前行。高水平战略协作是中朝关系的时代内涵。从朝方积极支持和响应构建人类命运共同体理念和四大全球倡议，到双方在联合国等多边平台保持沟通协作，再到围绕地区和国际问题加强协调，中朝双方坚定支持彼此维护国家主权、安全、发展利益，携手维护地区和平安宁、国际公平正义和战后国际秩序，不断为中朝传统友好注入新的时代内涵，为地区长治久安和世界和平发展注入稳定性。习近平总书记此次访问朝鲜，两党两国最高领导人把方向、谋大局、绘蓝图，加强对新时期中朝关系的顶层设计和战略指引，推动中朝关系与时俱进、得到更大发展。（二）维护好、巩固好、发展好中朝关系始终是中国党和政府坚定不移的方针。习近平总书记同金正恩会谈时指出：“无论国际形势如何变化，中国党和政府高度重视中朝传统友好的坚定立场不会改变，对金正恩总书记同志领导朝鲜社会主义事业的坚定支持不会改变，维护中朝双方共同利益和良好战略环境的坚定决心不会改变。”这“三个不会改变”为中朝关系行稳致远奠定了坚实基础、提供了不竭动力——中国党和政府高度重视中朝传统友好的坚定立场不会改变。中朝传统友谊是两党两国和两国人民共同的宝贵财富，这一传统友谊植根于双方共同的理想信念和奋斗目标，有深厚历史积淀、坚实政治基础、牢固情感纽带。世代友好、命运与共、守望相助是中朝关系的鲜明特征，历经时代变迁和国际风云变幻考验，中朝友好历久弥坚、万古长青。中国党和政府对金正恩总书记同志领导朝鲜社会主义事业的坚定支持不会改变。中国共产党和朝鲜劳动党同为马克思主义执政党，中朝两国是社会主义道路上的同行者，两党两国在长期的实践中相互支持、相互配合，为世界社会主义事业发展作出了重要贡献。两党两国最高领导人一致表示，要“携手开辟两国社会主义事业更加美好的前景”。中国党和政府维护中朝双方共同利益和良好战略环境的坚定决心不会改变。中朝在争取国家独立和民族解放的峥嵘岁月中，两国人民休戚与共、生死相依；在各自社会主义事业发展中，两国人民携手并肩、同甘共苦……中朝是守望相助的社会主义友好邻邦，坚定维护双方共同利益和良好战略环境，共同走好和平发展、合作共赢的人间正道。“三个不会改变”，彰显了中朝关系的特殊性，是推动两国关系高水平发展的定盘星。（三）当前，世界百年变局加速演进，中朝关系站在新的历史起点，面临新的发展机遇，肩负新的时代使命，两党两国最高领导人共同擘画了中朝关系的新蓝图。以高层交往为引领，夯实政治互信根基——一方面，保持两党两国高层交往优良传统，像亲戚一样常来往、多走动，引领中朝关系不断迈向新高度；另一方面，加强党政军各部门各层级沟通交往，落实好双方达成的重要共识，不断深化治党治国经验交流互鉴，为中朝关系发展汇聚智慧和力量。以为民造福为目标，提升务实合作水平——加强两国发展战略对接，挖掘各领域合作潜力，扩大经贸、农业、建筑、科技、医疗卫生等务实合作，共享机遇，共促发展，更好惠及两国人民。同时，以边境口岸全面复通、民航航班和国际客运列车恢复运营为契机，扩大人员往来，实现双向奔赴。以友谊传承为动力，拉紧民心相通纽带——中朝友谊符合两国人民心愿，符合两国根本利益，符合时代发展潮流，也是双方着眼长远大局作出的战略选择，不会因国际风云变幻而动摇。要通过灵活多样的形式，持续活跃友好往来，深化相互了解，拉紧情感纽带，让中朝传统友谊更加深入人心。以公平正义为理念，丰富战略协作内涵——世界进入新的动荡变革期，中朝两国应加强战略沟通和协调配合，坚定捍卫各自主权、安全、发展利益，共同维护地区和平与发展，反对霸权主义和强权政治，反对一切复活军国主义、危害地区安全稳定的图谋和行径，携手推动构建人类命运共同体。正如《中朝友谊之歌》所唱：“我们有伟大的友谊，我们有共同的理想，把我们团结得无比坚强。”习近平总书记对朝鲜进行国事访问具有历史性意义，将为两国传统友好注入穿越风雨、长久不衰的时代力量。央视新闻的微博视频', 1781000659, '2026-06-09 10:24:19+08:00', '62', '9', '11', 'https://m.weibo.cn/detail/5307843043133774', '中朝关系');
INSERT INTO `weibo_note` VALUES (64, '1618626114', '新时代中国外交思想库', 'https://tvax1.sinaimg.cn/crop.0.0.708.708.180/607a4642ly8gx6hyphv4mj20jo0joq44.jpg?KID=imgbed,tva&Expires=1780998180&ssig=7fpsvhUJ3a', 'm', 'https://m.weibo.cn/u/1618626114?luicode=20000061&lfid=5307882226322214&launchid=10000360-page_H5', '', 1780987390878, 1780987390878, 5307882226322214, '【#中朝关系必将乘风破浪勇往直前#】当地时间6月8日下午，#习近平同金正恩举行会谈#。在会谈时，习近平同金正恩共话中朝传统友谊，共商中朝关系发展大计。谈及中朝传统友谊，习近平用“三个不会改变”定调。当前，中朝关系站在新的历史起点，面临新的发展机遇，肩负新的时代使命。习近平提出的4点意见，为推动中朝关系与时俱进、得到更大发展提供了重要支撑。“岁月共磨砺，烈火见真金。”今年是《中朝友好合作互助条约》签订65周年，最高层战略引领是中朝关系的最大优势。中朝关系这艘航船有最高领导人领航掌舵，必将乘风破浪、勇往直前。#习近平访问朝鲜# 央视新闻的微博视频', 1781010001, '2026-06-09 13:00:01+08:00', '4', '0', '2', 'https://m.weibo.cn/detail/5307882226322214', '中朝关系');
INSERT INTO `weibo_note` VALUES (65, '1959444680', '云南网', 'https://tvax2.sinaimg.cn/crop.134.88.336.336.180/74cac0c8ly8h8vgzlnaw3j20gu0eawet.jpg?KID=imgbed,tva&Expires=1780998184&ssig=6Er%2FB%2FvjqW', 'm', 'https://m.weibo.cn/u/1959444680?luicode=20000061&lfid=5307882128016153&launchid=10000360-page_H5', '', 1780987390886, 1780987390886, 5307882128016153, '第一观察·瞬间 | 最隆重礼遇欢迎最尊贵客人网页链接 拾光纪·中朝两党两国最高领导人会谈，有这些关键词网页链接 独家视频丨习近平：时隔七年再次到访美丽的平壤 我感到十分高兴 也格外亲切网页链接 习近平和彭丽媛观看朝鲜专场文艺演出习近平和彭丽媛观看朝鲜专场文艺演出 为中朝传统友谊注入新的时代内涵和强劲动力，习近平提出“四个坚持”网页链接 习近平总书记署名文章为中朝关系迈向新高度提供指引网页链接 新华社评论员：把中朝传统友谊传承好发扬好网页链接', 1781009978, '2026-06-09 12:59:38+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307882128016153', '中朝关系');
