INSERT INTO `weibo_note` VALUES (67, '7474243489', '颍上县融媒体中心', 'https://tvax3.sinaimg.cn/crop.0.0.278.278.180/0089Paally8hv1u7g9keoj307q07qq2u.jpg?KID=imgbed,tva&Expires=1780998157&ssig=hxRqiUZ8lP', 'f', 'https://m.weibo.cn/u/7474243489?launchid=10000360-page_H5', '', 1780987390902, 1780987390902, 5307875406906841, '习近平总书记署名文章为中朝关系迈向新高度提供指引网页链接 ', 1781008375, '2026-06-09 12:32:55+08:00', '0', '0', '0', 'https://m.weibo.cn/detail/5307875406906841', '中朝关系');
